#!/usr/bin/env python3
"""Deterministic ACP fixture writing ONE harmless issue-scoped artifact.

A protocol integration test, NOT a general-purpose coding agent or LLM.
It deliberately ignores untrusted prompt text, executes no shell command,
does not fetch code and never accesses credentials or the network.
"""

import json
import os
from pathlib import Path
import sys

SESSION_ID = "kovan-acp-artifact-fixture"
ARTIFACT = Path("pilot/issue-1/acp.md")
BYTES = (
    b"# Kovan ACP integration fixture\n\n"
    b"Work item: yesvus/kovan#1\n"
    b"Generated by: disposable ACP JSON-RPC test peer\n"
    b"Result: deterministic, no LLM or GitHub credentials\n"
)


def emit(payload):
    print(json.dumps(payload, separators=(",", ":")), flush=True)


def write_fixture():
    """Use exclusive creation, never overwrite arbitrary preexisting content."""
    root = Path(os.environ.get("KOVAN_FIXTURE_ROOT", "/projects"))
    if not root.is_dir() or root.is_symlink():
        raise OSError("artifact workspace is unavailable")
    # Refuse intermediate symlinks before creating anything below them.
    # The disposable workspace is fresh and not shared with hostile processes.
    pilot = root / "pilot"
    if pilot.is_symlink():
        raise OSError("pilot workspace symlink forbidden")
    pilot.mkdir(exist_ok=True)
    if pilot.is_symlink():
        raise OSError("pilot workspace symlink forbidden")
    target_dir = pilot / "issue-1"
    if target_dir.is_symlink():
        raise OSError("artifact directory symlink forbidden")
    target_dir.mkdir(exist_ok=True)
    if target_dir.is_symlink():
        raise OSError("artifact directory symlink forbidden")
    path = root / ARTIFACT
    try:
        with path.open("xb") as stream:
            stream.write(BYTES)
    except FileExistsError:
        if path.is_symlink() or not path.is_file() or path.read_bytes() != BYTES:
            raise OSError("artifact already exists with different content")
    return len(BYTES)


def handle(request):
    if not isinstance(request, dict) or "id" not in request:
        return
    request_id = request["id"]
    method = request.get("method")
    if method == "initialize":
        result = {
            "protocolVersion": 1,
            "agentCapabilities": {
                "loadSession": False,
                "promptCapabilities": {
                    "image": False,
                    "audio": False,
                    "embeddedContext": False,
                },
            },
        }
    elif method == "session/new":
        result = {"sessionId": SESSION_ID}
    elif method == "session/prompt":
        try:
            write_fixture()
        except OSError:
            emit({
                "jsonrpc": "2.0", "id": request_id,
                "error": {"code": -32000, "message": "artifact fixture could not be written"},
            })
            return
        emit({
            "jsonrpc": "2.0",
            "method": "session/update",
            "params": {
                "sessionId": SESSION_ID,
                "update": {
                    "sessionUpdate": "agent_message_chunk",
                    "content": {
                        "type": "text",
                        "text": "KOVAN_ACP_ARTIFACT_WRITTEN",
                    },
                },
            },
        })
        result = {"stopReason": "end_turn"}
    else:
        emit({
            "jsonrpc": "2.0", "id": request_id,
            "error": {"code": -32601, "message": "Method not found"},
        })
        return
    emit({"jsonrpc": "2.0", "id": request_id, "result": result})


def main():
    for line in sys.stdin:
        try:
            data = json.loads(line)
        except (TypeError, ValueError):
            continue
        handle(data)


if __name__ == "__main__":
    main()
